CREATE TABLE IF NOT EXISTS public.account_audit(audit_id BIGSERIAL PRIMARY KEY,account_id BIGINT,old_balance NUMERIC(15,2),new_balance NUMERIC(15,2),changed_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE OR REPLACE FUNCTION public.audit_account_balance() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN IF OLD.balance IS DISTINCT FROM NEW.balance THEN INSERT INTO public.account_audit(account_id,old_balance,new_balance) VALUES(OLD.account_id,OLD.balance,NEW.balance); END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_account_balance_audit ON beginner.accounts;
CREATE TRIGGER trg_account_balance_audit AFTER UPDATE ON beginner.accounts FOR EACH ROW EXECUTE FUNCTION public.audit_account_balance();